solution.code:
.btn {
  background: #3b82f6;
  color: #fff;
  border: 0;
  padding: 12px 22px;
  border-radius: 8px;
  cursor: pointer;
  transition: transform 200ms ease-out, background 200ms ease-out;
}
.btn:hover {
  transform: scale(1.05);
  background: #1d4ed8;
}
